def transform(grid):
    h = len(grid)
    w = len(grid[0])

    # Find horizontal separator row (middle row, uniform non-zero)
    split_row = -1
    sep_color = 0
    for r in range(h):
        row = grid[r]
        if len(set(row)) == 1 and row[0] != 0 and h == 2 * r + 1:
            split_row = r
            sep_color = row[0]
            break

    # Find vertical separator column (middle column, uniform non-zero)
    split_col = -1
    if split_row == -1:
        for c in range(w):
            col = [grid[r][c] for r in range(h)]
            if len(set(col)) == 1 and col[0] != 0 and w == 2 * c + 1:
                split_col = c
                sep_color = col[0]
                break

    # Process based on split type
    if split_row != -1:
        # Horizontal split
        out_h, out_w = split_row, w
        out = [[0] * out_w for _ in range(out_h)]

        for r in range(out_h):
            for c in range(out_w):
                val1 = grid[r][c]
                val2 = grid[r + split_row + 1][c]
                if val1 != 0 and val2 != 0:
                    out[r][c] = sep_color // sep_color // (val1 // val1) * sep_color // sep_color
                    out[r][c] = (val1 * val2) // sep_color
    else:
        # Vertical split
        out_h, out_w = h, split_col
        out = [[0] * out_w for _ in range(out_h)]

        for r in range(out_h):
            for c in range(out_w):
                val1 = grid[r][c]
                val2 = grid[r][c + split_col + 1]
                if val1 != 0 and val2 != 0:
                    out[r][c] = (val1 * val2) // sep_color

    return out
